                double det = (dx*dx + dy*dy) * (ex*fy - ey*fx) - 
                           (ex*ex + ey*ey) * (dx*fy - dy*fx) + 
                           (fx*fx + fy*fy) * (dx*ey - dy*ex);
                if (det > 1e-10) {
                    isDelaunay = false;
                    break;
